#!/usr/bin/env node

/**
 * Exercises check-lockfile-sync.mjs against fixture repositories.
 *
 * Every fixture dependency resolves through the workspace protocol, so the whole
 * suite runs offline. The fixtures are real git repositories with a committed
 * lockfile, because the check compares regenerated bytes against committed ones —
 * which is also what a CI checkout gives it.
 *
 * A synced fixture and a desynced one are both required: a gate that cannot fail
 * is indistinguishable from one that cannot pass.
 *
 * `workspace-version-bumped` is the case that matters most. Whether a plain
 * `bun install` rewrites a stale recorded version is repo-dependent (see the
 * check's own docblock), and in these fixtures it does NOT — so this case fails if
 * the manifest comparison is ever removed, which is exactly the regression the
 * comparison exists to prevent.
 *
 * Fixtures are created under the OS temp dir. Point TMPDIR at a filesystem with
 * room if the default is a small tmpfs.
 */

import { execFileSync } from 'node:child_process';
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const checkScript = resolve(dirname(fileURLToPath(import.meta.url)), 'check-lockfile-sync.mjs');
const fixturePrefix = join(tmpdir(), 'oxy-lockfile-sync-');
const createdFixtures = [];
const failures = [];

function runCommand(command, args, cwd, extraEnvironment = {}) {
  try {
    const stdout = execFileSync(command, args, {
      cwd,
      encoding: 'utf8',
      env: { ...process.env, ...extraEnvironment },
      stdio: ['ignore', 'pipe', 'pipe'],
    });
    return { code: 0, output: stdout };
  } catch (error) {
    return {
      code: error.status ?? 1,
      output: `${error.stdout ?? ''}${error.stderr ?? ''}`,
    };
  }
}

function writeManifest(root, workspacePath, manifest) {
  const directory = join(root, workspacePath);
  mkdirSync(directory, { recursive: true });
  writeFileSync(join(directory, 'package.json'), `${JSON.stringify(manifest, null, 2)}\n`);
}

function rootManifest(overrides = {}) {
  return {
    name: 'fixture-root',
    private: true,
    version: '0.0.0',
    packageManager: 'bun@1.3.14',
    // An EXPLICIT path list, matching this repo's root manifest rather than a
    // `packages/*` glob — the shape the check has to model here.
    workspaces: ['packages/alpha', 'packages/beta'],
    devDependencies: { alpha: 'workspace:*', beta: 'workspace:*' },
    ...overrides,
  };
}

function createFixture() {
  const root = mkdtempSync(fixturePrefix);
  createdFixtures.push(root);
  writeManifest(root, '.', rootManifest());
  writeManifest(root, 'packages/alpha', {
    name: 'alpha',
    private: true,
    version: '1.0.0',
    dependencies: { beta: 'workspace:*' },
  });
  writeManifest(root, 'packages/beta', { name: 'beta', private: true, version: '2.0.0' });

  const install = runCommand('bun', ['install', '--ignore-scripts'], root);
  if (install.code !== 0) throw new Error(`Fixture install failed: ${install.output}`);

  for (const args of [
    ['init', '-q', '.'],
    ['add', '-A'],
    ['-c', 'user.email=fixture@example.invalid', '-c', 'user.name=fixture', 'commit', '-qm', 'fixture'],
  ]) {
    const step = runCommand('git', args, root);
    if (step.code !== 0) throw new Error(`Fixture git ${args[0]} failed: ${step.output}`);
  }
  return root;
}

function expectVerdict(caseName, root, expectedCode, expectedFragment) {
  const lockfileBefore = readFileSync(join(root, 'bun.lock'), 'utf8');
  const { code, output } = runCommand('bun', [checkScript], root);
  if (code !== expectedCode) {
    failures.push(`${caseName}: expected exit ${expectedCode}, got ${code}.\n${output}`);
    return;
  }
  if (!output.includes(expectedFragment)) {
    failures.push(`${caseName}: output does not contain ${JSON.stringify(expectedFragment)}.\n${output}`);
    return;
  }
  // Layer 2 installs to reach its verdict. A failing run must not leave the
  // regenerated lockfile behind, or the next run refuses with "already has
  // uncommitted changes" instead of reporting the desync again.
  if (expectedCode !== 0 && readFileSync(join(root, 'bun.lock'), 'utf8') !== lockfileBefore) {
    runCommand('git', ['checkout', '--', 'bun.lock'], root);
  }
}

// A lockfile matching its manifests must pass, or nothing below means anything.
expectVerdict('synced', createFixture(), 0, 'bun.lock is in sync with every package.json.');

// The mode layer 2 cannot see in these fixtures.
const versionFixture = createFixture();
writeManifest(versionFixture, 'packages/alpha', {
  name: 'alpha',
  private: true,
  version: '1.0.1',
  dependencies: { beta: 'workspace:*' },
});
expectVerdict(
  'workspace-version-bumped',
  versionFixture,
  1,
  'packages/alpha is at version "1.0.1" but bun.lock records "1.0.0"',
);

// A renamed workspace leaves every dependent's recorded range pointing at a name
// that no longer exists.
const renameFixture = createFixture();
writeManifest(renameFixture, 'packages/beta', { name: 'beta-renamed', private: true, version: '2.0.0' });
expectVerdict(
  'workspace-renamed',
  renameFixture,
  1,
  'packages/beta is named "beta-renamed" but bun.lock records "beta"',
);

// A declared workspace the lockfile never recorded.
const addedFixture = createFixture();
writeManifest(addedFixture, 'packages/gamma', { name: 'gamma', private: true, version: '3.0.0' });
writeManifest(addedFixture, '.', rootManifest({ workspaces: ['packages/alpha', 'packages/beta', 'packages/gamma'] }));
expectVerdict(
  'workspace-added',
  addedFixture,
  1,
  'packages/gamma is a declared workspace that bun.lock does not record.',
);

// An override changed without reinstalling pins something the lockfile does not.
const overrideFixture = createFixture();
writeManifest(overrideFixture, '.', rootManifest({ overrides: { beta: 'workspace:*' } }));
expectVerdict('override-added', overrideFixture, 1, 'override beta is');

// trustedDependencies is recorded in a different ORDER than declared, so it must
// be compared as a set — otherwise every run of this gate would cry wolf.
const trustedFixture = createFixture();
writeManifest(trustedFixture, '.', rootManifest({ trustedDependencies: ['beta'] }));
expectVerdict('trusted-dependencies-added', trustedFixture, 1, 'trustedDependencies is [beta]');

// A dependency removed from a manifest while the lockfile still resolves it —
// invisible to the manifest comparison, caught by the install.
const removedFixture = createFixture();
writeManifest(removedFixture, 'packages/alpha', { name: 'alpha', private: true, version: '1.0.0' });
expectVerdict('dependency-removed', removedFixture, 1, 'is OUT OF SYNC with the package.json files');

// An already-modified lockfile makes attribution impossible, so it must refuse
// rather than blame the commit for what was altered beforehand.
const dirtyFixture = createFixture();
writeFileSync(
  join(dirtyFixture, 'bun.lock'),
  `${readFileSync(join(dirtyFixture, 'bun.lock'), 'utf8')}\n`,
);
expectVerdict('dirty-lockfile', dirtyFixture, 1, 'already has uncommitted changes');

for (const fixture of createdFixtures) {
  if (fixture.startsWith(fixturePrefix)) rmSync(fixture, { recursive: true, force: true });
}

if (failures.length > 0) {
  console.error('Lockfile sync check tests failed:\n');
  for (const failure of failures) console.error(`- ${failure}`);
  process.exit(1);
}

console.log(`Lockfile sync check discriminated ${createdFixtures.length} fixture case(s).`);
